insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-pe-188","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Phosphorus has a higher first ionisation enthalpy than sulphur because of the extra stability of the","options":["filled 3s² 3p⁶ set","half-filled 3p³ configuration","empty 3d subshell of S","metallic bond in phosphorus"],"answer_index":1,"explanation":"P is 3p³; the paired 3p⁴ electron of S is easier to remove, so IE(P) > IE(S).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy"},{"id":"che-pe-189","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Between lithium and beryllium, beryllium has the greater first ionisation enthalpy because of its","options":["lower Zeff and 2p¹ configuration","higher Zeff and 2s² configuration","much larger radius","noble-gas core of argon"],"answer_index":1,"explanation":"Be is smaller, has one extra proton and a filled 2s pair, so IE₁(Be) > IE₁(Li).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy"},{"id":"che-pe-190","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The second ionisation enthalpy of sodium is very large because the second electron must be taken from the","options":["3s¹ valence orbital","neon-like 2p⁶ core","4s subshell","empty 3d set"],"answer_index":1,"explanation":"After loss of 3s¹, Na⁺ is isoelectronic with Ne; breaking that closed shell requires a large IE₂.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy"},{"id":"che-pe-191","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"First ionisation enthalpy falls in the order Li > Na > K because","options":["nuclear charge falls down the group","atomic size increases down the group","the number of valence electrons increases","they become noble gases"],"answer_index":1,"explanation":"The ns¹ electron is farther from the nucleus and more shielded in Na and K than in Li.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy"},{"id":"che-pe-192","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Although oxygen has a higher nuclear charge than nitrogen, its first ionisation enthalpy is lower because","options":["oxygen has the larger atomic radius","the extra electron in 2p⁴ is paired and is easier to remove","nitrogen has a filled 2p⁶ shell","oxygen lacks a 2s subshell"],"answer_index":1,"explanation":"Size would suggest IE(O) > IE(N), but pairing repulsion in 2p⁴ reverses the trend.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"ionization-enthalpy"},{"id":"che-pe-193","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Boron has a lower first ionisation enthalpy than beryllium even though B is smaller, because","options":["the 2p electron of B is shielded by 2s² and is easier to remove than a 2s electron of Be","boron has a noble-gas configuration","beryllium has a half-filled 2p set","nuclear charge falls from Be to B"],"answer_index":0,"explanation":"The two trends conflict: smaller size would raise IE, but the change of subshell (2s → 2p) lowers it, and the subshell effect wins.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"ionization-enthalpy"},{"id":"che-pe-194","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"For magnesium, the jump between IE₂ and IE₃ is much larger than between IE₁ and IE₂ because the third electron","options":["comes from the 3s subshell","comes from the neon core","is a 3p electron of Al","enters a 4s orbital"],"answer_index":1,"explanation":"Mg is 3s², so IE₁ and IE₂ remove valence electrons; IE₃ must break the 2p⁶ core and is therefore very large.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"ionization-enthalpy"},{"id":"che-pe-195","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electron gain enthalpy is the enthalpy change when an electron is added to a neutral gaseous atom to form a","options":["cation","uninegative ion","crystal lattice","hydrated proton"],"answer_index":1,"explanation":"The defining process is X(g) + e⁻ → X⁻(g); ΔegH is usually negative when energy is released.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-196","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A more negative electron gain enthalpy means a greater tendency of the atom to","options":["lose a proton","accept an electron","form a cation","expand its nucleus"],"answer_index":1,"explanation":"The more energy released on adding an electron, the more favourable the gain.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-197","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Halogens have the most negative electron gain enthalpies in their respective periods because they","options":["have empty valence shells","are one electron short of a noble-gas configuration","are the largest atoms of the period","cannot form anions"],"answer_index":1,"explanation":"Adding one electron completes ns² np⁶ and releases a large amount of energy.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-198","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Noble-gas atoms have positive electron gain enthalpies because the extra electron must","options":["pair in a half-filled p set","enter a new shell","remove a proton","form a metallic bond"],"answer_index":1,"explanation":"The incoming electron is added to a higher-n orbital against a closed shell, so energy must be supplied.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-199","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electron gain enthalpy generally becomes more negative on moving from left to right in a","options":["group","period","set of isotopes","metallic crystal"],"answer_index":1,"explanation":"Zeff rises and the vacancy is closer to the nucleus, so electron attachment is more exothermic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-200","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On moving down a halogen group, electron gain enthalpy generally becomes less negative after","options":["fluorine","chlorine","astatine","helium"],"answer_index":1,"explanation":"Cl has the most negative value; Br and I are less exothermic as the added electron is farther from the nucleus.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-201","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the first two halogens, the more negative electron gain enthalpy belongs to","options":["fluorine","chlorine","neon","sodium"],"answer_index":1,"explanation":"Cl is more exothermic than F, a well-known exception to the simple down-group trend.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-202","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The second electron gain enthalpy of an atom is always","options":["more negative than the first","positive","zero","equal to the first"],"answer_index":1,"explanation":"A negative ion must accept another electron, so energy is required and ΔegH₂ > 0.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-203","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Conversion of O⁻(g) to O²⁻(g) is endothermic because a negative ion must","options":["lose two protons","accept another electron against its own charge","enter the 1s shell","become a cation"],"answer_index":1,"explanation":"Electron–electron repulsion in O⁻ makes the second attachment unfavourable; oxides form in the lattice, not as free O²⁻(g).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-204","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electron affinity is often quoted as the negative of the","options":["ionisation enthalpy","electron gain enthalpy","electronegativity","atomic radius"],"answer_index":1,"explanation":"Many older tables list EA as a positive number equal to −ΔegH when attachment is exothermic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain"},{"id":"che-pe-205","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine has a less negative electron gain enthalpy than chlorine because the compact 2p cloud of F suffers","options":["almost no inter-electronic repulsion","strong electron–electron repulsion when an extra electron is added","a vacant 3d subshell","lanthanoid contraction"],"answer_index":1,"explanation":"The incoming electron is forced into a very small 2p orbital already crowded with electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain"},{"id":"che-pe-206","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among F, Cl, Br and I, the most negative electron gain enthalpy belongs to","options":["fluorine","chlorine","bromine","iodine"],"answer_index":1,"explanation":"Chlorine combines a high Zeff with a large enough 3p orbital to avoid the extreme repulsion seen in F.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain"},{"id":"che-pe-207","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Nitrogen has a near-zero or slightly positive electron gain enthalpy because its 2p subshell is already","options":["empty","half filled","completely filled","a d subshell"],"answer_index":1,"explanation":"Adding an electron to 2p³ forces pairing and destroys the half-filled stability, so attachment is unfavourable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-pe-188","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-189","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-190","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-191","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-192","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-193","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-194","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-195","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-196","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-197","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-198","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-199","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-200","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-201","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-202","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-203","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-204","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-205","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-206","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-207","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
